package service

import (
	_ "embed"
	"encoding/json"
	"math"
	"sort"
	"strings"
	"sync"
)

// The quiz bank is generated by scripts/build_quiz_bank.py from the two source CSVs and
// committed. It is embedded rather than loaded at runtime because it never changes between
// deploys, and because the alternative — writing a 7 MB payload into a Go raw string —
// would break on the first backtick in a question stem. That has happened four times in
// this package already.
//
// 题库由 scripts/build_quiz_bank.py 从两份源 CSV 生成后提交，走 embed 而不是运行时读取：
// 它在两次部署之间不会变；而写成 Go 原始字符串的话，题干里出现一个反引号就会截断整个
// 常量——这个包里已经踩过四次。
//
//go:embed assets/quiz/bank.json
var quizBankJSON []byte

// Question kinds. The numbers are produced by the Python builder and must stay in sync.
const (
	quizKindSingle = 1 // 单选
	quizKindMulti  = 2 // 多选
	quizKindJudge  = 3 // 判断
	quizKindSubj   = 4 // 主观题（名词解释/简答/论述/病例）
	quizKindBlank  = 5 // 已挖空的填空句，答案是句中被挖掉的那一段
)

// quizQuestion is one bank row plus its precomputed term ids.
//
// Terms are stored as ids into a shared vocabulary rather than as strings: the bank holds
// ~13k questions and each one contributes 20–40 bigrams, so keeping the strings per
// question would cost tens of megabytes of duplicated headers. Ids intersect in a
// two-pointer walk and the weights live in one flat slice.
//
// quizQuestion 是一行题库记录加上预先算好的词 id。
//
// 词以 id 形式存放而不是字符串：题库约一万三千题，每题贡献 20–40 个 bigram，若每题各存一份
// 字符串，光切片头与指针就是几十 MB 的重复。用 id 之后求交变成两个有序切片的双指针遍历，
// 权重只存在一个平坦数组里。
type quizQuestion struct {
	Kind     int      `json:"k"`
	Type     string   `json:"t,omitempty"`
	Stem     string   `json:"s"`
	Options  []string `json:"o,omitempty"`
	Answer   string   `json:"a"`
	Recovery string   `json:"r,omitempty"`
	Subject  string   `json:"u,omitempty"`
	Chapter  string   `json:"c,omitempty"`
	// School and Year are the exam this question came from, e.g. 四川大学 2015. Two short
	// fields rather than one pre-joined label: the renderer decides whether to show them
	// together, and a joined string cannot be sorted or filtered later.
	//
	// School 与 Year 是这道题的出处考试，如 四川大学 2015。用两个短字段而不是一个拼好的标签：
	// 由渲染层决定要不要一起显示，而拼死的字符串日后没法再排序或筛选。
	School string `json:"sc,omitempty"`
	Year   string `json:"yr,omitempty"`

	terms []int32 // sorted, deduplicated term ids
}

// QuizHit is one matched question as the render path needs it.
//
// Shared and Coverage exist so an offline probe can explain *why* a question was chosen.
// Without them a wrong match looks the same as a right one.
//
// QuizHit 是渲染路径需要的单条命中。
//
// Shared 与 Coverage 是为了让离线探针能解释"为什么选了这道题"——没有它们的话，
// 配错的题和配对的题看起来一模一样。
type QuizHit struct {
	Kind     int
	Type     string
	Stem     string
	Options  []string
	Answer   string
	Recovery string
	Subject  string
	Chapter  string
	School   string
	Year     string

	Score    float64
	Coverage float64
	// SharedIDF is the summed idf of the terms this question and the note both contain.
	// Coverage alone cannot separate "shares three rare terms" from "shares three generic
	// bigrams such as 牙体/缺损/修复", and that distinction is the whole difference between
	// a good match and an off-chapter one.
	//
	// SharedIDF 是题目与笔记共有的那些词的 idf 之和。只看 coverage 分不清"命中了三个罕见词"
	// 与"命中了牙体/缺损/修复 三个泛词"——而这两者的差别正是对题与跑偏题的全部差别。
	SharedIDF float64
	Shared    []string
}

type quizBankIndex struct {
	questions []*quizQuestion
	vocab     map[string]int32
	// terms is the reverse of vocab: id -> token text. Kept so a diagnostic can print the
	// shared terms behind a match instead of a column of integers.
	//
	// terms 是 vocab 的逆映射：id → 词文本。留着它，诊断时就能打印出"凭什么匹配上"的
	// 那几个词，而不是一列整数。
	terms []string
	idf   []float32
	// df is the document frequency per term id, kept so a diagnostic can say "this match
	// rides on 多见于, which appears in 412 questions" rather than only its weight.
	//
	// df 是每个词 id 的文档频次，留着它诊断时才说得出"这次匹配靠的是多见于，
	// 它出现在 412 道题里"，而不是只报一个权重数字。
	df []int32
	// maxIDF is the weight of a term that occurs in exactly one document. The containment
	// denominators divide by sums of idf, and an empty question vocabulary would divide by
	// zero, so the value doubles as the fallback.
	//
	// maxIDF 是只出现在一篇文档里的词的权重。containment 的分母是 idf 之和，
	// 题干词表为空时会除以零，因此它同时充当兜底值。
	maxIDF float32
}

var (
	quizBankOnce sync.Once
	quizBank     *quizBankIndex
)

// QuizOptions carries the matching thresholds. They live in a struct rather than as
// constants inside the loop so the offline probe can sweep them and report what each value
// would cost, instead of the values being decided once by intuition and never revisited.
//
// QuizOptions 承载匹配阈值。做成结构体而不是循环里的常量，是为了让离线探针能扫一遍、
// 报告每个取值要付出什么代价；否则这些数字就是凭直觉定一次、此后再无人复核。
type QuizOptions struct {
	// MinShared is the minimum number of distinct terms a question and a note must both
	// contain. One shared bigram happens between any two dental notes.
	//
	// MinShared 是题目与笔记至少共有的不同词数。任意两篇口腔笔记都会共享一个 bigram。
	MinShared int

	// MinLongShared is the minimum number of shared terms that must be at least three
	// runes long. This is the gate that separates a real topical match from an accident.
	//
	// Measured on the vault: 釉梭多见于 is an enamel question, and a note about enamel
	// structure does not contain 釉梭 — yet it scored 0.545 by sharing only bigrams
	// (第一/磨牙/牙尖/牙牙/乳牙). Every genuine match in the same sample shared at least
	// one trigram or full run (第一磨, 牙釉质, 的主要). One long shared term is therefore
	// the cheapest available proof that the two texts are talking about the same thing,
	// because the tokenizer only emits long tokens for exact character sequences.
	//
	// MinLongShared 是"至少要有几个长度 ≥3 的公共词"。
	// 实测依据：釉梭多见于 是釉质题，而讲釉质结构的笔记并不含「釉梭」——它靠只共享
	// bigram（第一/磨牙/牙尖/牙牙/乳牙）拿到了 0.545 分。同批样本里每一个真匹配都至少
	// 共享一个三元组或整串（第一磨、牙釉质、的主要）。因此"有一个长公共词"是当前最便宜的
	// 证据，证明两段文字在讲同一件事——分词器只对精确字符序列才产出长词。
	MinLongShared int

	// MinScore is the absolute floor on the match score (see QuizMatchWith for the formula).
	// Coverage alone is reported for diagnosis but never gates: a ratio cannot tell "the
	// note is about this" from "the note happens to contain these words".
	//
	// MinScore 是匹配分数的绝对下限（公式见 QuizMatchWith）。覆盖率只用于诊断、不参与过滤：
	// 一个比例分不清"笔记讲的就是这个"和"笔记恰好包含这几个字"。
	MinScore float64

	// SubjectBoost multiplies the score when both subjects are known and agree.
	// SubjectPenalty applies when they disagree; it is a penalty rather than a filter
	// because only 17% of the bank carries a subject and rows do get mislabelled.
	//
	// SubjectBoost 在双方学科已知且一致时乘上去；不一致时用 SubjectPenalty。
	// 用惩罚而不是过滤，是因为题库里只有 17% 带学科，且确实存在标错的行。
	SubjectBoost   float64
	SubjectPenalty float64
}

// DefaultQuizOptions are the values the render path runs with. They were chosen by sweeping
// the offline probe over all 95 notes — see 交接-16 §12.
//
// DefaultQuizOptions 是渲染路径实际使用的值，由离线探针在全部 95 篇笔记上扫出来后确定，
// 见 交接-16 §12。
func DefaultQuizOptions() QuizOptions {
	return QuizOptions{
		MinShared:      quizMinSharedTerms,
		MinLongShared:  quizMinLongShared,
		MinScore:       quizMinScore,
		SubjectBoost:   quizSubjectBoost,
		SubjectPenalty: quizSubjectPenalty,
	}
}

const (
	// quizMinSharedTerms rejects questions that share only one term with the note. One
	// bigram in common happens between any two dental notes — the same argument the
	// tokenizer's own comment makes about 颌第.
	//
	// quizMinSharedTerms 拒绝与笔记只有一个共同词的题。任意两篇口腔笔记都会共享一两个
	// bigram——分词器注释里关于「颌第」的那段说的是同一件事。
	quizMinSharedTerms = 3

	// quizMinLongShared see QuizOptions.MinLongShared.
	quizMinLongShared = 1

	// quizMinScore is the absolute floor on the match score. Calibrated on the vault by
	// scripts + cmd/quizprobe; see 交接-16 §12 for the sweep that produced it.
	//
	// quizMinScore 是匹配分数的绝对下限，由 cmd/quizprobe 在真实笔记库上扫出，见 交接-16 §12。
	quizMinScore = 3.0

	// quizSubjectBoost nudges a question whose subject matches the note's own subject.
	// It is deliberately small: only 17% of the bank carries a subject, and a
	// mis-filed row should still be able to win on content.
	//
	// quizSubjectBoost 给学科一致的题一点加成。刻意很小：题库里只有 17% 带学科，
	// 一行标错了学科的题仍应有机会凭内容胜出。
	quizSubjectBoost = 1.10

	// quizSubjectPenalty applies when both sides are known and disagree. Also small, for
	// the same reason — misfiled questions are common in this bank.
	//
	// quizSubjectPenalty 用于双方学科都已知且不一致时。同样很小，理由相同：这份题库里
	// 标错学科的情况并不少见。
	quizSubjectPenalty = 0.92
)

// loadQuizBank parses the embedded bank and builds the vocabulary, idf table and per-question
// term ids. It runs once, on the first quiz request, so a deployment that never serves a
// quiz never pays for it.
//
// loadQuizBank 解析内嵌题库并构建词表、idf 与每题词 id。只在第一次练习请求时运行一次，
// 因此从不提供练习的部署不会为它付出代价。
func loadQuizBank() *quizBankIndex {
	quizBankOnce.Do(func() {
		var payload struct {
			V int             `json:"v"`
			Q []*quizQuestion `json:"q"`
		}
		if err := json.Unmarshal(quizBankJSON, &payload); err != nil {
			// A malformed embedded asset is a build-time mistake, not a runtime condition.
			// Serving an empty bank keeps the rest of the blog alive; the quiz section
			// simply does not render, which is the documented degraded state.
			//
			// 内嵌资源损坏是构建期错误，不是运行时状况。给出空题库能让博客其余部分继续
			// 工作；练习区不渲染——这正是文档里写明的降级状态。
			quizBank = &quizBankIndex{}
			return
		}

		idx := &quizBankIndex{
			questions: payload.Q,
			vocab:     make(map[string]int32, 1<<17),
		}

		// Pass 1: assign term ids and collect document frequencies.
		df := make([]int32, 0, 1<<17)
		tokens := make([]string, 0, 1<<17)
		for _, q := range payload.Q {
			qt := askTokenize(quizSearchText(q))
			ids := make([]int32, 0, len(qt))
			for _, t := range qt {
				id, ok := idx.vocab[t]
				if !ok {
					id = int32(len(df))
					idx.vocab[t] = id
					df = append(df, 0)
					tokens = append(tokens, t)
				}
				ids = append(ids, id)
			}
			sort.Slice(ids, func(i, j int) bool { return ids[i] < ids[j] })
			ids = compactInt32(ids)
			// A token that repeats inside one question counts once toward df: this is a
			// presence index, not a term-frequency index.
			//
			// 同一题内重复出现的词对 df 只计一次：这是存在性索引，不是词频索引。
			for _, id := range ids {
				df[id]++
			}
			q.terms = ids
		}
		idx.terms = tokens
		idx.df = df

		n := float64(len(payload.Q))
		idx.idf = make([]float32, len(df))
		for i, d := range df {
			idx.idf[i] = float32(math.Log((n+1)/float64(d+1)) + 1)
			if idx.idf[i] > idx.maxIDF {
				idx.maxIDF = idx.idf[i]
			}
		}
		if idx.maxIDF <= 0 {
			idx.maxIDF = 1
		}
		quizBank = idx
	})
	return quizBank
}

// quizSearchText is the text a question is indexed by: its stem, its options, and — for
// subjective questions only — its answer. Including an objective question's answer letter
// would add noise such as "a" to the vocabulary; including a subjective answer is exactly
// right, because a 名词解释's answer is where the terminology lives.
//
// quizSearchText 是一道题被索引时使用的文本：题干、选项，以及——只对主观题——答案。
// 把客观题的答案字母也放进来会往词表里塞进 "a" 之类的噪声；而主观题的答案正是术语所在，
// 放进来才是对的。
func quizSearchText(q *quizQuestion) string {
	var b strings.Builder
	b.WriteString(q.Stem)
	if len(q.Options) > 0 {
		b.WriteString(" ")
		b.WriteString(strings.Join(q.Options, " "))
	}
	if q.Kind == quizKindSubj || q.Kind == quizKindBlank {
		b.WriteString(" ")
		b.WriteString(q.Answer)
	}
	return b.String()
}

// compactInt32 removes adjacent duplicates from a sorted slice.
func compactInt32(s []int32) []int32 {
	if len(s) < 2 {
		return s
	}
	out := s[:1]
	for _, v := range s[1:] {
		if v != out[len(out)-1] {
			out = append(out, v)
		}
	}
	return out
}

// QuizMatch ranks bank questions against a note's plain text.
//
// The score is a *directional* containment, not BM25: it asks "how much of this question's
// information does the note already talk about", which is the question a chapter-end
// exercise needs to answer. A symmetric similarity would reward long questions that happen
// to share a heading, and punish short ones that are perfectly on topic.
//
// QuizMatch 用笔记纯文本给题库排序。
//
// 打分是**有方向的**覆盖率，而不是 BM25：它问的是"这道题的信息有多少已经在笔记里讲过了"，
// 这正是章末练习需要回答的问题。对称相似度会奖励那些恰好复述了某个小标题的长题，
// 而惩罚真正切题的短题。
func QuizMatch(notePlain, subjectHint string, topObjective, topSubjective int) ([]QuizHit, []QuizHit) {
	return QuizMatchWith(notePlain, subjectHint, topObjective, topSubjective, DefaultQuizOptions())
}

// QuizMatchWith is QuizMatch with explicit thresholds, used by the offline probe to sweep
// candidate values against the real vault.
//
// QuizMatchWith 是带显式阈值的 QuizMatch，供离线探针用真实笔记库扫候选取值。
func QuizMatchWith(notePlain, subjectHint string, topObjective, topSubjective int, opt QuizOptions) ([]QuizHit, []QuizHit) {
	idx := loadQuizBank()
	if len(idx.questions) == 0 {
		return nil, nil
	}

	noteTokens := askTokenize(notePlain)
	if len(noteTokens) == 0 {
		return nil, nil
	}
	// Term frequency is counted per line rather than per document: askTokenize returns a
	// deduplicated set, and re-implementing it with counts would fork the tokenizer — the
	// one thing in this package that everything else depends on being identical. Counting
	// per line keeps the tokenizer authoritative and still yields the only statistic this
	// code needs: how central a term is to the note. A note about 贴面 says 贴面 on thirty
	// lines; it mentions 全冠 on two.
	//
	// 词频按行累计而不是按篇：askTokenize 返回的是去重后的集合，若为计数再实现一份分词器，
	// 就等于把这个包里所有东西都依赖一致性的那个函数复制成两份。按行计数保持了分词器的
	// 唯一权威，同时给出了这段代码唯一需要的统计量——一个词在笔记里有多核心。
	// 讲贴面的笔记有三十行提到「贴面」，而「全冠」只有两行。
	noteTF := make(map[int32]float32, len(noteTokens))
	for _, line := range strings.Split(notePlain, "\n") {
		for _, t := range askTokenize(line) {
			if id, ok := idx.vocab[t]; ok {
				noteTF[id]++
			}
		}
	}
	if len(noteTF) == 0 {
		return nil, nil
	}

	candidates := make([]QuizHit, 0, 64)
	for _, q := range idx.questions {
		if len(q.terms) < opt.MinShared {
			continue
		}
		var den, num float32
		shared := make([]string, 0, 8)
		longShared := 0
		for _, t := range q.terms {
			w := idx.idf[t]
			den += w
			if tf, ok := noteTF[t]; ok && tf > 0 {
				num += w * (1 + float32(math.Log1p(float64(tf))))
				term := idx.terms[t]
				shared = append(shared, term)
				if len([]rune(term)) >= 3 {
					longShared++
				}
			}
		}
		if den == 0 {
			continue
		}
		if len(shared) < opt.MinShared || longShared < opt.MinLongShared {
			continue
		}
		// Score grows with the rarity of the shared terms and with how much the note
		// dwells on them, and is only square-root normalised by the question's own
		// weight. Linear normalisation (a plain ratio) systematically favoured short
		// questions that share three generic bigrams over a long question that shares the
		// one term the note is actually about — measured on 贴面.
		//
		// 分数随公共词的稀有度和笔记对它的着墨程度增长，只按题目自身权重做平方根归一。
		// 线性归一（纯比例）会系统性地偏向"共享三个泛词"的短题，而压掉"共享笔记真正在讲的
		// 那一个词"的长题——这一点在贴面那篇上实测到了。
		score := float64(num / float32(math.Sqrt(float64(den))))
		coverage := float64(num / den)
		if score < opt.MinScore {
			continue
		}

		if q.Subject != "" && subjectHint != "" && q.Subject == subjectHint {
			score *= opt.SubjectBoost
		} else if q.Subject != "" && subjectHint != "" && q.Subject != subjectHint {
			score *= opt.SubjectPenalty
		}

		candidates = append(candidates, QuizHit{
			Kind:      q.Kind,
			Type:      q.Type,
			Stem:      q.Stem,
			Options:   q.Options,
			Answer:    q.Answer,
			Recovery:  q.Recovery,
			Subject:   q.Subject,
			Chapter:   q.Chapter,
			School:    q.School,
			Year:      q.Year,
			Score:     score,
			Coverage:  float64(coverage),
			SharedIDF: float64(num),
			Shared:    shared,
		})
	}

	sort.SliceStable(candidates, func(a, b int) bool {
		if candidates[a].Score != candidates[b].Score {
			return candidates[a].Score > candidates[b].Score
		}
		return candidates[a].Stem < candidates[b].Stem
	})

	var objective, subjective []QuizHit
	seen := make(map[string]struct{}, len(candidates))
	for _, c := range candidates {
		key := quizStemKey(c.Stem)
		if _, dup := seen[key]; dup {
			continue
		}
		if c.Kind == quizKindSubj {
			if len(subjective) < topSubjective {
				subjective = append(subjective, c)
				seen[key] = struct{}{}
			}
			continue
		}
		if len(objective) < topObjective {
			objective = append(objective, c)
			seen[key] = struct{}{}
		}
		if len(objective) >= topObjective && len(subjective) >= topSubjective {
			break
		}
	}
	return objective, subjective
}

// quizStemKey is the dedup key for near-identical stems that survived the build-time dedup
// because their punctuation differed.
//
// quizStemKey 用来去掉构建期去重漏掉的那些"只差标点"的重复题干。
func quizStemKey(s string) string {
	var b strings.Builder
	for _, r := range s {
		switch {
		case r >= 'a' && r <= 'z', r >= '0' && r <= '9':
			b.WriteRune(r)
		case r >= 'A' && r <= 'Z':
			b.WriteRune(r + ('a' - 'A'))
		case r >= 0x4e00 && r <= 0x9fff:
			b.WriteRune(r)
		}
	}
	return b.String()
}

// QuizBankSize reports how many questions the embedded bank holds. Used by the offline
// probe and by the settings log line, so an empty bank is visible without guessing.
//
// QuizBankSize 返回内嵌题库的题数，供离线探针与启动日志使用，
// 让"题库是空的"这件事不必靠猜。
func QuizBankSize() int {
	return len(loadQuizBank().questions)
}

// QuizTermStats returns a token's document frequency and idf, or zeros when the token is
// absent from the bank. Diagnostic only.
//
// QuizTermStats 返回某个词的文档频次与 idf，词不在题库里时返回零。仅用于诊断。
func QuizTermStats(token string) (df int32, idf float64) {
	idx := loadQuizBank()
	id, ok := idx.vocab[token]
	if !ok {
		return 0, 0
	}
	return idx.df[id], float64(idx.idf[id])
}

// QuizBankIDFStats returns idf percentiles so the probe can report the actual scale of the
// weight table. Tuning a threshold against a guessed range is how thresholds end up either
// inert or destructive.
//
// QuizBankIDFStats 返回 idf 的分位数，让探针能报出权重表的真实量级。
// 对着猜出来的区间调阈值，结果只会是阈值要么形同虚设要么误杀。
func QuizBankIDFStats() (p50, p90, p99, max float64) {
	idx := loadQuizBank()
	if len(idx.idf) == 0 {
		return 0, 0, 0, 0
	}
	vals := make([]float32, len(idx.idf))
	copy(vals, idx.idf)
	sort.Slice(vals, func(i, j int) bool { return vals[i] < vals[j] })
	at := func(p float64) float64 {
		i := int(p * float64(len(vals)-1))
		return float64(vals[i])
	}
	return at(0.50), at(0.90), at(0.99), float64(vals[len(vals)-1])
}
